package com.jnapanam.sportszone.admin.controller;import com.jnapanam.sportszone.booking.dto.BookingResponse;import com.jnapanam.sportszone.booking.service.BookingService;import java.util.UUID;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/operations")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public class OperationsController{private final BookingService bookings;public OperationsController(BookingService b){bookings=b;}@PostMapping("/bookings/{bookingNumber}/check-in")public BookingResponse checkIn(Authentication a,@PathVariable String bookingNumber){return bookings.checkIn(UUID.fromString(a.getName()),bookingNumber);}}
